<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\StaticPage; use Illuminate\Http\Request; use Illuminate\Support\Str;
class StaticPageController extends Controller { public function create(){return view('admin.static-page-form',['page'=>new StaticPage]);} public function edit(StaticPage $page){return view('admin.static-page-form',compact('page'));} public function store(Request $r){$d=$r->validate(['title'=>'required|max:255','slug'=>'nullable|max:255|unique:static_pages,slug','content'=>'nullable','status'=>'required|in:draft,published', 'meta_title'=>'nullable|max:255', 'meta_description'=>'nullable', 'meta_keywords'=>'nullable', 'robots'=>'nullable|max:100']);$d['slug']=$d['slug']?:Str::slug($d['title']);StaticPage::create($d);return redirect()->route('admin.footer-settings.edit')->with('success','Static page created.');} public function update(Request $r,StaticPage $page){$d=$r->validate(['title'=>'required|max:255','slug'=>'nullable|max:255|unique:static_pages,slug,'.$page->id,'content'=>'nullable','status'=>'required|in:draft,published', 'meta_title'=>'nullable|max:255', 'meta_description'=>'nullable', 'meta_keywords'=>'nullable', 'robots'=>'nullable|max:100']);$d['slug']=$d['slug']?:Str::slug($d['title']);$page->update($d);return redirect()->route('admin.footer-settings.edit')->with('success','Static page updated.');} }
